/**
 * The QR code printed on every share picture (docs/native-app-store-plan.md Phase 9b).
 * Pure data, safe in the browser; also read by scripts/generate-share-qr.cjs.
 *
 * It encodes ONLY `APP_DOWNLOAD_URL` (Phase 9a's permanent `/app` link): a posted Story
 * lives in camera rolls forever, so the value can never move. The picture is drawn on the
 * player's phone from this pre-generated file — no encoder in the bundle, no server work.
 * tests/share-card-qr.test.ts decodes the file and fails if it drifts from the constant.
 * Changing the value means `npm run share:qr` AND a new file name (old pictures keep theirs).
 */

import { APP_DOWNLOAD_URL } from "@/lib/appDownloadLink";

export const SHARE_QR_VALUE = APP_DOWNLOAD_URL;

/** Error-correction level. Q survives Instagram's recompression and a cracked phone screen. */
export const SHARE_QR_LEVEL = "Q" as const;

/** Quiet zone, in modules (the QR spec minimum), baked into the file's white background. */
export const SHARE_QR_MARGIN = 4;

/** Pixels per module in the file. The cards draw it at a whole multiple, never smoothed. */
export const SHARE_QR_PX_PER_MODULE = 16;

/** Generated by `npm run share:qr`; committed under public/. */
export const SHARE_QR_SRC = "/share/app-download-qr-v1.png";

/** Modules per side, quiet zone included (version 3 at level Q). Pinned by the decode test. */
export const SHARE_QR_MODULES = 37;
